B.QQ=new A.bc("evening-3","Submission by Night and Day","Allahumma bika amsayna wa bika asbahna","\u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0628\u0650\u0643\u064e \u0623\u064e\u0645\u0652\u0633\u064e\u064a\u0652\u0646\u064e\u0627\u060c \u0648\u064e\u0628\u0650\u0643\u064e \u0623\u064e\u0635\u0652\u0628\u064e\u062d\u0652\u0646\u064e\u0627\u060c \u0648\u064e\u0628\u0650\u0643\u064e \u0646\u064e\u062d\u0652\u064a\u064e\u0627\u060c \u0648\u064e\u0628\u0650\u0643\u064e \u0646\u064e\u0645\u064f\u0648\u062a\u064f\u060c \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u0627\u0644\u0652\u0645\u064e\u0635\u0650\u064a\u0631\u064f","Allahumma bika amsayna, wa bika asbahna, wa bika nahya, wa bika namootu, wa ilaykal-maseer","O Allah, by Your leave we have reached the evening, and by Your leave we have reached the morning; by Your leave we live, by Your leave we die, and unto You is our final destination.","At-Tirmidhi 3391 | Abu Dawood 5068",1,"The standard evening sunnah acknowledgement of reliance on Allah.","https://www.duaandazkar.com/audio_new/CH2DUA3.mp3",B.a57)
B.a2O=s(["ruqyah","sick","visiting","healing","cure"],t.s)
B.QR=new A.bc("ruqyah-6","Visiting the Sick Person (7x)","As'alullahal-'Adheema Rabbal-'Arshil-'Adheem","\u0623\u064e\u0633\u0652\u0623\u064e\u0644\u064f \u0627\u0644\u0644\u064e\u0651\u0647\u064e \u0627\u0644\u0652\u0639\u064e\u0638\u0650\u064a\u0645\u064e \u0631\u064e\u0628\u064e\u0651 \u0627\u0644\u0652\u0639\u064e\u0631\u0652\u0634\u0650 \u0627\u0644\u0652\u0639\u064e\u0638\u0650\u064a\u0645\u0650 \u0623\u064e\u0646\u0652 \u064a\u064e\u0634\u0652\u0641\u0650\u064a\u064e\u0643\u064e","As'alullahal-'Adheema Rabbal-'Arshil-'Adheemi an yashfiyak","I ask Allah the Almighty, Lord of the Magnificent Throne, to heal you.","Abu Dawood 3106 | At-Tirmidhi 2083",7,"The Prophet \ufdfa said: 'No Muslim visits a sick person whose appointed time has not come and says this seven times, except that Allah will cure him.'","https://www.duaandazkar.com/audio_new/CH6DUA6.mp3",B.a2O)
