B.UN=new A.cM(101,"The Sweetness of Faith","\u062b\u064e\u0644\u0627\u064e\u062b\u064c \u0645\u064e\u0646\u0652 \u0643\u064f\u0646\u064e\u0651 \u0641\u0650\u064a\u0647\u0650 \u0648\u064e\u062c\u064e\u062f\u064e \u062d\u064e\u0644\u0627\u064e\u0648\u064e\u0629\u064e \u0627\u0644\u0625\u0650\u064a\u0645\u064e\u0627\u0646\u0650: \u0623\u064e\u0646\u0652 \u064a\u064e\u0643\u064f\u0648\u0646\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064f\u0647\u064f \u0623\u064e\u062d\u064e\u0628\u064e\u0651 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u0645\u0650\u0645\u064e\u0651\u0627 \u0633\u0650\u0648\u064e\u0627\u0647\u064f\u0645\u064e\u0627\u060c \u0648\u064e\u0623\u064e\u0646\u0652 \u064a\u064f\u062d\u0650\u0628\u064e\u0651 \u0627\u0644\u0652\u0645\u064e\u0631\u0652\u0621\u064e \u0644\u0627\u064e \u064a\u064f\u062d\u0650\u0628\u064f\u0651\u0647\u064f \u0625\u0650\u0644\u0627\u064e\u0651 \u0644\u0650\u0644\u064e\u0651\u0647\u0650\u060c \u0648\u064e\u0623\u064e\u0646\u0652 \u064a\u064e\u0643\u0652\u0631\u064e\u0647\u064e \u0623\u064e\u0646\u0652 \u064a\u064e\u0639\u064f\u0648\u062f\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0643\u064f\u0641\u0652\u0631\u0650 \u0643\u064e\u0645\u064e\u0627 \u064a\u064e\u0643\u0652\u0631\u064e\u0647\u064f \u0623\u064e\u0646\u0652 \u064a\u064f\u0642\u0652\u0630\u064e\u0641\u064e \u0641\u0650\u064a \u0627\u0644\u0646\u064e\u0651\u0627\u0631\u0650","Whoever possesses three qualities will taste the sweetness of faith: that Allah and His Messenger are more beloved to him than anything else; that he loves a person only for Allah's sake; and that he hates to return to disbelief as he would hate to be thrown into the fire.","Anas ibn Malik (RA)","Sahih Al-Bukhari 16, Sahih Muslim 43","Muttafaq 'Alayh (Sahih)","Faith is not merely a dry intellectual assent; it produces real inner delight and emotional sweetness when love of Allah guides one's priorities.","Faith & Tawheed")
B.UG=new A.cM(102,"Faith Has Over Seventy Branches","\u0627\u0644\u0625\u0650\u064a\u0645\u064e\u0627\u0646\u064f \u0628\u0650\u0636\u0652\u0639\u064c \u0648\u064e\u0633\u064e\u0628\u0652\u0639\u064f\u0648\u0646\u064e - \u0623\u064e\u0648\u0652 \u0628\u0650\u0636\u0652\u0639\u064c \u0648\u064e\u0633\u0650\u062a\u064f\u0651\u0648\u0646\u064e - \u0634\u064f\u0639\u0652\u0628\u064e\u0629\u064b\u060c \u0641\u064e\u0623\u064e\u0641\u0652\u0636\u064e\u0644\u064f\u0647\u064e\u0627 \u0642\u064e\u0648\u0652\u0644\u064f \u0644\u0627\u064e \u0625\u0650\u0644\u064e\u0647\u064e \u0625\u0650\u0644\u0627\u064e\u0651 \u0627\u0644\u0644\u064e\u0651\u0647\u064f\u060c \u0648\u064e\u0623\u064e\u062f\u0652\u0646\u064e\u0627\u0647\u064e\u0627 \u0625\u0650\u0645\u064e\u0627\u0637\u064e\u0629\u064f \u0627\u0644\u0623\u064e\u0630\u064e\u0649 \u0639\u064e\u0646\u0650 \u0627\u0644\u0637\u064e\u0651\u0631\u0650\u064a\u0642\u0650\u060c \u0648\u064e\u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0621\u064f \u0634\u064f\u0639\u0652\u0628\u064e\u0629\u064c \u0645\u0650\u0646\u064e \u0627\u0644\u0625\u0650\u064a\u0645\u064e\u0627\u0646\u0650","Faith has over seventy branches: the highest is saying 'La ilaha illallah' (None has the right to be worshipped but Allah), and the lowest is removing a harmful obstacle from the road, and modesty (Haya') is a branch of faith.","Abu Hurairah (RA)","Sahih Muslim 35","Sahih Muslim","Shows that faith connects the highest theological proclamation with simple everyday public courtesy, like clearing litter from walkways.","Faith & Tawheed")
B.a5U=s([B.UN,B.UG],t.NQ)
B.UB=new A.i4(1,"Faith & Tawheed","\u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0648\u0627\u0644\u062a\u0648\u062d\u064a\u062f","\u2728",B.a5U)
B.UW=new A.cM(201,"Heaviest on the Scales on Judgment Day","\u0645\u064e\u0627 \u0634\u064e\u064a\u0652\u0621\u064c \u0623\u064e\u062b\u0652\u0642\u064e\u0644\u064f \u0641\u0650\u064a \u0645\u0650\u064a\u0632\u064e\u0627\u0646\u0650 \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650 \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u0645\u0650\u0646\u0652 \u062e\u064f\u0644\u064f\u0642\u064d \u062d\u064e\u0633\u064e\u0646\u064d\u060c \u0648\u064e\u0625\u0650\u0646\u064e\u0651 \u0627\u0644\u0644\u064e\u0651\u0647\u064e \u0644\u064e\u064a\u064f\u0628\u0652\u063a\u0650\u0636\u064f \u0627\u0644\u0652\u0641\u064e\u0627\u062d\u0650\u0634\u064e \u0627\u0644\u0652\u0628\u064e\u0630\u0650\u064a\u0621\u064e","Nothing is heavier upon the scale of a believer on the Day of Resurrection than good character. Indeed, Allah detests the foul-mouthed and obscene person.","Abu Ad-Darda (RA)","Jami' At-Tirmidhi 2002","Sahih At-Tirmidhi","Good character (Akhlaq) carries more weight on the divine scales than countless voluntary rituals done with harshness.","Noble Character & Akhlaq")
B.UQ=new A.cM(202,"Smiling is Charity","\u062a\u064e\u0628\u064e\u0633\u064f\u0651\u0645\u064f\u0643\u064e \u0641\u0650\u064a \u0648\u064e\u062c\u0652\u0647\u0650 \u0623\u064e\u062e\u0650\u064a\u0643\u064e \u0644\u064e\u0643\u064e \u0635\u064e\u062f\u064e\u0642\u064e\u0629\u064c","Your smiling in the face of your brother is charity for you.","Abu Dharr (RA)","Jami' At-Tirmidhi 1956","Sahih","Spreading joy, friendliness, and warmth costs nothing but earns divine reward equivalent to financial charity.","Noble Character & Akhlaq")
